def _source_before_share188_observation(relative, text):
    """Only the exact per-request observation may reconstruct retained Share172 source."""
    if relative != _SHARE188_OBSERVATION["path"]:
        return text
    if _sha256(text) != _SHARE188_OBSERVATION["after_sha256"]:
        raise ValueError("Exact Share188 observation host postimage is required")
    for fragment in reversed(_SHARE188_OBSERVATION["fragments"]):
        if (hashlib.sha256(fragment["before"].encode()).hexdigest() != fragment["before_fragment_sha256"] or
                hashlib.sha256(fragment["after"].encode()).hexdigest() != fragment["after_fragment_sha256"] or
                text.count(fragment["after"]) != 1):
            raise ValueError("Exact unique Share188 host inverse is required")
        text = text.replace(fragment["after"], fragment["before"], 1)
    if _sha256(text) != _SHARE188_OBSERVATION["before_sha256"]:
        raise ValueError("Share188 inverse changed original host assertions or lease bytes")
    return text


def _read_sources():
    return {relative: _support_before_fixture_repair169(relative,
                _source_before_compiler_repair172(relative,
                    _source_before_share188_observation(relative, (ROOT / relative).read_bytes().decode("utf-8"))))
            for relative in (*_SPEC["changed_paths"], *_SPEC["support_paths"])}


def _admit_sources(sources):
    """Exact owning postimage admission/in-memory inverse, not a native state model."""
    expected = set(_SPEC["changed_paths"]) | set(_SPEC["support_paths"])
    if set(sources) != expected:
        raise ValueError("Exact owning source paths and retained support are required")
    reconstructed = {}
    for relative in _SPEC["changed_paths"]:
        text = sources[relative]
        if _sha256(text) != _SPEC["postimage_sha256"][relative]:
            raise ValueError("Exact reviewed owning source postimage is required")
        for fragment in reversed(_SPEC["fragments"][relative]):
            if text.count(fragment["after"]) != 1:
                raise ValueError("Exact unique owning source fragment is required")
            text = text.replace(fragment["after"], fragment["before"], 1)
        if _sha256(text) != _SPEC["preimage_sha256"][relative]:
            raise ValueError("Exact preserved Share002 owning source preimage is required")
        reconstructed[relative] = text
    for relative in _SPEC["support_paths"]:
        if _sha256(sources[relative]) != _SPEC["support_sha256"][relative]:
            raise ValueError("Exact unchanged controlled/source support bytes are required")
    for relative, names in _SPEC["retained_native_methods"].items():
        observed = re.findall(r"@Test\s+fun\s+(\w+)\s*\(", sources[relative])
        if observed != names:
            raise ValueError("Exact original13 native source identities are required")
    return reconstructed


class IosShareOwnedRootBarrierControls(unittest.TestCase):
    def _sources(self):
        sources = _read_sources()
        _admit_sources(sources)
        return sources

    def _refuse_cases(self, sources, method):
        for case in _SPEC["mutation_cases"][method]:
            with self.subTest(refusal=case["label"]):
                self.assertEqual(1, sources[case["path"]].count(case["before"]))
                mutated = dict(sources)
                mutated[case["path"]] = mutated[case["path"]].replace(case["before"], case["after"], 1)
                with self.assertRaises(ValueError):
                    _admit_sources(mutated)

