        self.assertIn('owner = IosShareOwner(parent) { deliveries += it }\n            retainIosShareOwner(owner)\n            launcher = ShareLauncher(owner::launch)', native)
        self.assertIn('launcher.also { retainIosShareOwner(assertNotNull(it.currentIosOwner)) }', native)
